  (() => {
    const raw = $('Set Config1').item.json.trigger_word || '';
    const text = String($json.text || '');

    // escape any regex chars in the trigger word
    const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    // support multiple comma-separated trigger words
    const triggers = raw.toString()
      .split(',')
      .map(w => w.trim())
      .filter(Boolean);

    // check whole-word match: \bWORD\b (case-insensitive)
    return triggers.some(w => new RegExp(`\\b${esc(w)}\\b`, 'i').test(text));
  })()
}}

