// Dates in ISO (yyyy-LL-dd)
const today        = DateTime.now().toFormat('yyyy-LL-dd');
const sevenDaysAgo = DateTime.now().minus({ days: 7 }).toFormat('yyyy-LL-dd');

// helpers
const norm = v => String(v ?? '').trim().toLowerCase();
const toISO = v => {
  if (!v) return null;
  const d = DateTime.fromISO(String(v));
  return d.isValid ? d.toFormat('yyyy-LL-dd') : null;
};

const out = [];
for (const item of items) {
  const r = item.json || {};

  // must already be connected (DM sent)
  const isDmSent      = norm(r.dm_status) === 'sent';

  // follow-up not yet sent
  const needsFollowup = norm(r.followup_status) === 'not_sent';

  // date logic: due if next_followup_at <= today,
  // else if dm_sent_at <= sevenDaysAgo,
  // else (no dates) treat as due
  const nextISO = toISO(r.next_followup_at);
  const dmISO   = toISO(r.dm_sent_at);
  const dueByNext   = nextISO && nextISO <= today;
  const dueByDmDate = dmISO && dmISO <= sevenDaysAgo;
  const due = (dueByNext || dueByDmDate || (!nextISO && !dmISO)); // if no dates, include

  if (isDmSent && needsFollowup && due) {
    out.push(item);
  }
}

return out;
